/** The `StableOrd` half of `impl_stable_traits_for_trivial_type!`. */
export function StableOrd_trivial<T>(cmp: (a: T, b: T) => Ordering): StableOrd<T> {
  return { CAN_USE_UNSTABLE_SORT: true, cmp };
}

// We need a custom impl as the default hash function will only hash half the bits. For stable
// hashing we want to hash the full 128-bit hash.
// rustc: compiler/rustc_data_structures/src/stable_hash.rs:216 stable_hash
export function stable_hash_Hash128(self: Hash128, _: StableHashCtxt, hasher: StableHasher): void {
  // `self.as_u128().hash(hasher)`
  hasher.write_u128(self);
}

