// rustc: compiler/rustc_data_structures/src/stable_hash.rs:247 stable_hash
/** `impl StableHash for f32`: hashes `to_bits()` as a `u32`. */
export function stable_hash_f32(self: number, hcx: StableHashCtxt, hasher: StableHasher): void {
  const buf = new DataView(new ArrayBuffer(4));
  buf.setFloat32(0, self, true);
  const val: number = buf.getUint32(0, true);
  stable_hash_u32(val, hcx, hasher);
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:254 stable_hash
/** `impl StableHash for f64`: hashes `to_bits()` as a `u64`. */
export function stable_hash_f64(self: number, hcx: StableHashCtxt, hasher: StableHasher): void {
  const buf = new DataView(new ArrayBuffer(8));
  buf.setFloat64(0, self, true);
  const val: bigint = buf.getBigUint64(0, true);
  stable_hash_u64(val, hcx, hasher);
}

