/** `impl<T1: StableHash> StableHash for (T1,)` */
export function stable_hash_tuple1<T1>(self: readonly [T1], hcx: StableHashCtxt, hasher: StableHasher, h1: StableHash<T1>): void {
  const [_0] = self;
  h1(_0, hcx, hasher);
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:276 stable_hash
/** `impl<T1: StableHash, T2: StableHash> StableHash for (T1, T2)` */
export function stable_hash_tuple2<T1, T2>(
  self: readonly [T1, T2],
  hcx: StableHashCtxt,
  hasher: StableHasher,
  h1: StableHash<T1>,
  h2: StableHash<T2>,
): void {
  const [_0, _1] = self;
  h1(_0, hcx, hasher);
  h2(_1, hcx, hasher);
}

/** `impl<T1: StableOrd, T2: StableOrd> StableOrd for (T1, T2)` */
export function StableOrd_tuple2<T1, T2>(o1: StableOrd<T1>, o2: StableOrd<T2>): StableOrd<readonly [T1, T2]> {
  // Ordering of tuples is a pure function of their elements' ordering, and since
  // the ordering of each element is stable so must be the ordering of the tuple.
  return {
    CAN_USE_UNSTABLE_SORT: o1.CAN_USE_UNSTABLE_SORT && o2.CAN_USE_UNSTABLE_SORT,
    cmp: (a, b) => o1.cmp(a[0], b[0]) || o2.cmp(a[1], b[1]),
  };
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:297 stable_hash
/** `impl<T1, T2, T3> StableHash for (T1, T2, T3)` */
export function stable_hash_tuple3<T1, T2, T3>(
  self: readonly [T1, T2, T3],
  hcx: StableHashCtxt,
  hasher: StableHasher,
  h1: StableHash<T1>,
  h2: StableHash<T2>,
  h3: StableHash<T3>,
): void {
  const [_0, _1, _2] = self;
  h1(_0, hcx, hasher);
  h2(_1, hcx, hasher);
  h3(_2, hcx, hasher);
}

/** `impl<T1: StableOrd, T2: StableOrd, T3: StableOrd> StableOrd for (T1, T2, T3)` */
export function StableOrd_tuple3<T1, T2, T3>(o1: StableOrd<T1>, o2: StableOrd<T2>, o3: StableOrd<T3>): StableOrd<readonly [T1, T2, T3]> {
  // Ordering of tuples is a pure function of their elements' ordering, and since
  // the ordering of each element is stable so must be the ordering of the tuple.
  return {
    CAN_USE_UNSTABLE_SORT: o1.CAN_USE_UNSTABLE_SORT && o2.CAN_USE_UNSTABLE_SORT && o3.CAN_USE_UNSTABLE_SORT,
    cmp: (a, b) => o1.cmp(a[0], b[0]) || o2.cmp(a[1], b[1]) || o3.cmp(a[2], b[2]),
  };
}

