/** `impl<T: StableHash> StableHash for [T]` (the `default fn`; `[u8]` is `stable_hash_bytes`). */
export function stable_hash_slice<T>(self: readonly T[], hcx: StableHashCtxt, hasher: StableHasher, stable_hash_T: StableHash<T>): void {
  stable_hash_usize(self.length, hcx, hasher);
  for (const item of self) {
    stable_hash_T(item, hcx, hasher);
  }
}

