/** `impl<K, V, R> StableHash for indexmap::IndexMap<K, V, R>`. PORT: an `IndexMap` is a JS `Map` (insertion-ordered). */
export function stable_hash_IndexMap<K, V>(
  self: ReadonlyMap<K, V>,
  hcx: StableHashCtxt,
  hasher: StableHasher,
  stable_hash_K: StableHash<K>,
  stable_hash_V: StableHash<V>,
): void {
  stable_hash_usize(self.size, hcx, hasher);
  for (const kv of self) {
    stable_hash_tuple2(kv, hcx, hasher, stable_hash_K, stable_hash_V);
  }
}

