/** `impl StableHash for str`: `self.as_bytes()`. PORT: a JS string (hashed as its UTF-8 bytes). */
export function stable_hash_str(self: string, hcx: StableHashCtxt, hasher: StableHasher): void {
  stable_hash_bytes(utf8(self), hcx, hasher);
}

/** `impl StableOrd for &str` (`CAN_USE_UNSTABLE_SORT = true`): byte-wise (UTF-8) order. */
export const StableOrd_str: StableOrd<string> = {
  // Encoding and decoding doesn't change the bytes of string slices
  // and `Ord::cmp` depends only on those bytes.
  CAN_USE_UNSTABLE_SORT: true,
  cmp: (a, b) => cmp_bytes(utf8(a), utf8(b)),
};

function cmp_bytes(a: Uint8Array, b: Uint8Array): Ordering {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) if (a[i] !== b[i]) return a[i]! < b[i]! ? -1 : 1;
  return a.length < b.length ? -1 : a.length > b.length ? 1 : 0;
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:448 stable_hash
/** `impl StableHash for String`: `self[..]`. */
export function stable_hash_String(self: string, hcx: StableHashCtxt, hasher: StableHasher): void {
  stable_hash_str(self, hcx, hasher);
}

/** `impl StableOrd for String`: string comparison only depends on their contents and the contents
 * are not changed by (de-)serialization. */
export const StableOrd_String: StableOrd<string> = StableOrd_str;

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:463 stable_hash
/** `impl StableHash for bool`: `1u8` / `0u8`. */
export function stable_hash_bool(self: boolean, hcx: StableHashCtxt, hasher: StableHasher): void {
  stable_hash_u8(self ? 1 : 0, hcx, hasher);
}

/** `impl StableOrd for bool`: sort order of bools is not changed by (de-)serialization. */
export const StableOrd_bool: StableOrd<boolean> = {
  CAN_USE_UNSTABLE_SORT: true,
  cmp: (a, b) => (a === b ? 0 : a ? 1 : -1),
};

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:480 stable_hash
/**
 * `impl<T: StableHash> StableHash for Option<T>`. PORT: `Option<T>` is `T | undefined`; an
 * `Option` of an undefined-able `T` (`{ $: "Some", _0 } | undefined`, PORTING §5) is
 * `stable_hash_Option_some`.
 */
export function stable_hash_Option<T>(self: T | undefined, hcx: StableHashCtxt, hasher: StableHasher, stable_hash_T: StableHash<T>): void {
  if (self !== undefined) {
    const value = self;
    stable_hash_u8(1, hcx, hasher);
    stable_hash_T(value, hcx, hasher);
  } else {
    stable_hash_u8(0, hcx, hasher);
  }
}

/** `stable_hash_Option` for the `{ $: "Some", _0 }` encoding of `Option<Option<T>>`-like values. */
export function stable_hash_Option_some<T>(
  self: { readonly $: "Some"; readonly _0: T } | undefined,
  hcx: StableHashCtxt,
  hasher: StableHasher,
  stable_hash_T: StableHash<T>,
): void {
  if (self !== undefined) {
    stable_hash_u8(1, hcx, hasher);
    stable_hash_T(self._0, hcx, hasher);
  } else {
    stable_hash_u8(0, hcx, hasher);
  }
}

/** `impl<T: StableOrd> StableOrd for Option<T>`: the Option wrapper does not add instability to comparison. */
export function StableOrd_Option<T>(t: StableOrd<T>): StableOrd<T | undefined> {
  return {
    CAN_USE_UNSTABLE_SORT: t.CAN_USE_UNSTABLE_SORT,
    // `None < Some(_)`
    cmp: (a, b) => (a === undefined ? (b === undefined ? 0 : -1) : b === undefined ? 1 : t.cmp(a, b)),
  };
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:503 stable_hash
/** `impl<T1, T2> StableHash for Result<T1, T2>` */
export function stable_hash_Result<T1, T2>(
  self: Result<T1, T2>,
  hcx: StableHashCtxt,
  hasher: StableHasher,
  stable_hash_T1: StableHash<T1>,
  stable_hash_T2: StableHash<T2>,
): void {
  // `mem::discriminant(self)`: `Ok` = 0, `Err` = 1.
  stable_hash_Discriminant(self.$ === "Ok" ? 0 : 1, hcx, hasher);
  switch (self.$) {
    case "Ok":
      stable_hash_T1(self._0, hcx, hasher);
      break;
    case "Err":
      stable_hash_T2(self._0, hcx, hasher);
      break;
  }
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:517 stable_hash
/** `impl<'a, T: StableHash + ?Sized> StableHash for &'a T`. PORT: `&T` is `T`. */
export function stable_hash_ref<T>(self: T, hcx: StableHashCtxt, hasher: StableHasher, stable_hash_T: StableHash<T>): void {
  stable_hash_T(self, hcx, hasher);
}

/**
 * The integer type of `<T as DiscriminantKind>::Discriminant`: the enum's `#[repr(..)]` integer,
 * `isize` without one.
 */
export type DiscriminantRepr = "isize" | "i8" | "i16" | "i32" | "u8" | "u16" | "u32" | "usize";

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:524 stable_hash
/**
 * `impl<T> StableHash for ::std::mem::Discriminant<T>`: `Hash::hash(self, hasher)`, which hashes
 * the discriminant value as its integer type (`isize` unless the enum has an integer `#[repr]`).
 * PORT: a `Discriminant<T>` is the discriminant value plus that type.
 */
export function stable_hash_Discriminant(self: number, _: StableHashCtxt, hasher: StableHasher, repr: DiscriminantRepr = "isize"): void {
  switch (repr) {
    case "isize":
      hasher.write_isize(self);
      return;
    case "i8":
      hasher.write_i8(self);
      return;
    case "i16":
      hasher.write_i16(self);
      return;
    case "i32":
      hasher.write_i32(self);
      return;
    case "u8":
      hasher.write_u8(self);
      return;
    case "u16":
      hasher.write_u16(self);
      return;
    case "u32":
      hasher.write_u32(self);
      return;
    case "usize":
      hasher.write_usize(self);
      return;
  }
}

/** `std::range::RangeInclusive<T>` (the new-style range: `start`, `last`). */
export interface RangeInclusive<T> {
  start: T;
  last: T;
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:534 stable_hash
/** `impl<T: StableHash> StableHash for ::std::range::RangeInclusive<T>` */
export function stable_hash_RangeInclusive<T>(self: RangeInclusive<T>, hcx: StableHashCtxt, hasher: StableHasher, stable_hash_T: StableHash<T>): void {
  stable_hash_T(self.start, hcx, hasher);
  stable_hash_T(self.last, hcx, hasher);
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:544 stable_hash
/** `impl<I: Idx, T: StableHash> StableHash for IndexSlice<I, T>`. PORT: an `IndexSlice` is `T[]`. */
export function stable_hash_IndexSlice<T>(self: readonly T[], hcx: StableHashCtxt, hasher: StableHasher, stable_hash_T: StableHash<T>): void {
  stable_hash_usize(self.length, hcx, hasher);
  for (const v of self) {
    stable_hash_T(v, hcx, hasher);
  }
}

