// `impl_stable_traits_for_trivial_type!(::std::ffi::OsStr)`: `impl Hash for OsStr` hashes
// `as_encoded_bytes()` as a `[u8]` (`write_length_prefix` + one `write`).
// PORT: an `OsStr` is its encoded bytes.
export function stable_hash_OsStr(self: Uint8Array, _: StableHashCtxt, hasher: StableHasher): void {
  hasher.write_length_prefix(self.length);
  hasher.write(self);
}

// `impl_stable_traits_for_trivial_type!(::std::path::Path)` / `(::std::path::PathBuf)`: std's
// `impl Hash for Path` (src/std/path.ts `path_hash`). PORT: paths are strings (src/std/path.ts).
export function stable_hash_Path(self: string, _: StableHashCtxt, hasher: StableHasher): void {
  path_hash(self, path_hasher(hasher));
}
export function stable_hash_PathBuf(self: string, hcx: StableHashCtxt, hasher: StableHasher): void {
  // `impl Hash for PathBuf`: `self.as_path().hash(h)`
  stable_hash_Path(self, hcx, hasher);
}

/** src/std/path.ts's `Hasher` view of a `StableHasher` (its `write_usize` takes a 64-bit `bigint`). */
export function path_hasher(hasher: StableHasher): PathHasher {
  return {
    write: (bytes) => hasher.write(bytes),
    write_u8: (i) => hasher.write_u8(i),
    // `write_usize` widens to a u64: the same bytes as `write_u64`.
    write_usize: (i) => hasher.write_u64(i),
    write_isize: (i) => hasher.write_isize(i),
    write_length_prefix: (len) => hasher.write_length_prefix(len),
  };
}

// It is not safe to implement StableHash for HashSet, HashMap or any other collection type
// with unstable but observable iteration order.
// See https://github.com/rust-lang/compiler-team/issues/533 for further information.
// (`impl<V> !StableHash for std::collections::HashSet<V> {}` / `HashMap<K, V>`: no TS impl.)

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:592 stable_hash
/**
 * `impl<K: StableHash + StableOrd, V: StableHash> StableHash for BTreeMap<K, V>`.
 * PORT: a `BTreeMap` is a `Map` iterated in key order: `ord` is `K`'s `StableOrd`.
 */
export function stable_hash_BTreeMap<K, V>(
  self: ReadonlyMap<K, V>,
  hcx: StableHashCtxt,
  hasher: StableHasher,
  stable_hash_K: StableHash<K>,
  stable_hash_V: StableHash<V>,
  ord: StableOrd<K>,
): void {
  stable_hash_usize(self.size, hcx, hasher);
  for (const entry of [...self].sort((a, b) => ord.cmp(a[0], b[0]))) {
    stable_hash_tuple2(entry, hcx, hasher, stable_hash_K, stable_hash_V);
  }
}

// rustc: compiler/rustc_data_structures/src/stable_hash.rs:604 stable_hash
/** `impl<K: StableHash + StableOrd> StableHash for BTreeSet<K>`. PORT: a `Set` iterated in key order. */
export function stable_hash_BTreeSet<K>(
  self: ReadonlySet<K>,
  hcx: StableHashCtxt,
  hasher: StableHasher,
  stable_hash_K: StableHash<K>,
  ord: StableOrd<K>,
): void {
  stable_hash_usize(self.size, hcx, hasher);
  for (const entry of [...self].sort(ord.cmp)) {
    stable_hash_K(entry, hcx, hasher);
  }
}

/// Controls what data we do or do not hash.
/// Whenever a `StableHash` implementation caches its
/// result, it needs to include `StableHashControls` as part
/// of the key, to ensure that it does not produce an incorrect
/// result (for example, using a `Fingerprint` produced while
/// hashing `Span`s when a `Fingerprint` without `Span`s is
/// being requested)
// `#[derive(Clone, Copy, Hash, Eq, PartialEq, Debug)]`
export interface StableHashControls {
  hash_spans: boolean;
}

export const debug_StableHashControls: Debug<StableHashControls> = (v, f) =>
  debug_struct(f, "StableHashControls", [["hash_spans", debug_bool(v.hash_spans, f)]]);

export function StableHashControls_eq(a: StableHashControls, b: StableHashControls): boolean {
  return a.hash_spans === b.hash_spans;
}
